<template lang="pug">
.page-container
    .page-title 心理師班表
    select.labelSelector(v-model='semester_label')
        option(value='') 請選擇學期標籤
        option(v-for='option in labelOption' :key='option.label' :value='option.label') {{ option.label }}
    el-row(:gutter="20")
        el-col(:sm="24" :md="12")
            el-table.list-container(:data="counselors" style="width: 100%")
                el-table-column(prop="name" label="姓名" width="100")
                el-table-column(prop="gender" label="性別" width="60")
                el-table-column(prop="employment_type" label="聘用類別" width="90")
                el-table-column(prop="semester_label" label="學期")
                el-table-column(prop="available_time" label="可諮商時段")
                    template(#header='')
                        el-popover(placement="right" title="" :width="200" trigger="hover" popper-class="weektimePop")
                            div(v-html="getHtmlContent()")
                            template(#reference)
                                span 可諮商時段
                                    QuestionFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
                    template(#default='scope')
                        div {{scope.row.available_time}}
                el-table-column(v-if="cases.data" prop="assign_time" label="目前排班狀況")
                    template(#default='scope')
                        div(v-for="item in getCasesByCounselorId(scope.row.id)") {{item.consultation_day}}{{item.consultation_time}}-{{item.name}} | {{item.crisis_level}}
        el-col(:sm="24" :md="12")
            div(style="display:flex;")
                div 0/{{counselorNum}}
                div.color-box
                    .color-box-item(v-for="i in maxNum+1" :style="'background-color: rgba(242, 164, 75, '+(i-1)/maxNum+');width: '+100/maxNum+'%;'")
                div {{maxNum}}/{{counselorNum}} (有排班人數/總人數)
            .counselor-time-table(v-if="countAvailable().length>1")
                el-row
                    el-col.picker-col-lable.row-border(:span="4")
                    el-col.picker-col.row-border(v-for="day in days" :span="4") {{day.label}}
                el-row.picker-row(v-for="(time,i) in times" justify="space-around" :style="!Number.isInteger(time.value)?'border-top: 2px solid #F2A54B':''")
                    el-col.picker-col-lable(:span="4") {{time.label}}
                    el-col.picker-col(v-for="(day,j) in days" :span="4" :style="'background-color: rgba(242, 164, 75, '+countAvailable()[j][i]/maxNum+')'")
</template>

<script>
import {weektimeMixin} from "@/components/weektimeMixin"
export default {
    mixins: [weektimeMixin],
    data () {
        return {
            counselorNum: -1,
            maxNum: 0,
            semester_label: '',
            labelOption: [],
        }
    },
    async created() {
        await this.$store.dispatch('fetchCounselors')
        await this.$store.dispatch('fetchAssignCases')
        await this.$store.dispatch('fetchSemesterLabel')
        this.labelOption = this.$store.state.semester_label.data
    },
    computed: {
        counselors() {
            if (this.semester_label !== '')
                return this.$store.state.counselors.filter(counselor => counselor.semester_label === this.semester_label)
            else
                return this.$store.state.counselors
        },
        cases() {
            return this.$store.state.assignCases
        }
    },
    methods: {
        countAvailable() {
            // Init
            this.counselorNum = this.counselors.length
            var [r, c] = [this.days.length, this.times.length]
            var timeTable = Array(r).fill().map(()=>Array(c).fill(0))
            this.counselors.forEach(counselor => {
                if(counselor.available_time!="") {
                    counselor.available_time.split(',').forEach(time => {
                        let aAry = time.split('')
                        aAry[0] = parseInt(this.dayRule[aAry[0]])-1
                        aAry[1] = parseInt(this.timeRule[aAry[1]])-1
                        if(!timeTable[aAry[0]][aAry[1]]) timeTable[aAry[0]][aAry[1]]=1
                        else timeTable[aAry[0]][aAry[1]] += 1

                        if(timeTable[aAry[0]][aAry[1]]>this.maxNum) this.maxNum = timeTable[aAry[0]][aAry[1]]
                    })
                }
            })
            return timeTable
        },
        getCasesByCounselorId(id) {
            let cases = this.cases.data.filter(e => e.counselor_id == id)
            cases.sort((a,b) => {
                let aDay = this.dayRule[a.consultation_day]
                let bDay = this.dayRule[b.consultation_day]
                if(aDay == bDay){
                    return this.timeRule[a.consultation_time]-this.timeRule[b.consultation_time]
                }
                else{
                    return this.dayRule[a.consultation_day]-this.dayRule[b.consultation_day]
                }
            })
            return cases
        }
    }
}
</script>
<style lang="sass" scoped>
@import "@/style/common.sass"
.color-box
    border: 1px solid $GrayBorder
    height: 20px
    width: 100px
    margin: 0 10px
    display: flex
.color-box-item 
    height: 100%
    background-color: $BaseBorder
.picker-row
    border-bottom: 1px solid $LightBorder
    text-align: center
    user-select: none
.picker-col-lable
    word-wrap: break-word
    text-align: center
    padding: 3px
.picker-col
    word-wrap: break-word
    border-left: 1px solid $LightBorder
    text-align: center
    padding: 3px
.row-border
    border-bottom: 2px solid #F2A54B
.counselor-time-table
    @include tableBorder()
    margin: 20px 0
    background-color: #fff
    overflow: hidden

.labelSelector
    width: 200px
    margin-bottom: 20px
</style>
